/**
 * The DSL's checks, before sending: field -> message, empty when nothing is
 * wrong. The server checks them again; this is so a form can say it first.
 * partial: an update that sends only what changed - what is required is not asked for.
 */
export function validateLead(value: Partial<LeadDTO> | null | undefined, partial = false): Record<string, string> {
    const errors: Record<string, string> = {};
    if (value == null) return errors;
    if (partial ? value.company === '' : (value.company == null || value.company === '')) errors.company = "회사명 is required";
    else if (value.company != null && String(value.company).length > 100) errors.company = "회사명 is at most 100 characters";
    if (partial ? value.contactName === '' : (value.contactName == null || value.contactName === '')) errors.contactName = "담당자 이름 is required";
    else if (value.contactName != null && String(value.contactName).length > 50) errors.contactName = "담당자 이름 is at most 50 characters";
    if (value.email != null && String(value.email).length > 100) errors.email = "이메일 is at most 100 characters";
    else if (value.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(String(value.email))) errors.email = 'Email format invalid';
    if (value.phone != null && String(value.phone).length > 20) errors.phone = "전화번호 is at most 20 characters";
    if (value.estimatedValue != null && Number(value.estimatedValue) < 0) errors.estimatedValue = "예상 금액 must be at least 0";
    return errors;
}

